   480	static void startup_poll_cb(lv_timer_t * tmr)
   481	{
   482	    startup_page_t * ui = (startup_page_t *)lv_timer_get_user_data(tmr);
   483	    uint32_t elapsed;
   484	    unsigned next;
   485	
   486	    if (!ui || ui->exiting) {
   487	        return;
   488	    }
   489	
   490	    helm_splash_pump(&ui->splash);
   491	
   492	    elapsed = lv_tick_elaps(ui->appear_tick);
   493	
   494	    /* Host already on USB: skip map file preparation (same LittleFS as MTP). */
   495	    {
   496	        myvendor_mtp_status_t mtp_st;
   497	
   498	        memset(&mtp_st, 0, sizeof(mtp_st));
   499	        (void)myvendor_mtp_get_status(&mtp_st);
   500	        if (mtp_st.plug >= MYVENDOR_MTP_PLUG_ENUM) {
   501	            startup_begin_exit(ui);
   502	            return;
   503	        }
   504	    }
   505	
   506	    /* 底色已按主题铺好：开机音播完再进 settle，chrome 露出后才跑 GPX/字体/地图。 */
   507	    if (!ui->bg_started) {
   508	        if (ui->sound_wait) {
   509	            if (!myvendor_sound_idle()) {
   510	                return;
   511	            }
   512	
   513	            ui->sound_wait = false;
   514	            startup_start_bg_anim(ui);
   515	        }
   516	
   517	        return;
   518	    }
   519	
   520	    /* 白屏还在恢复 GPX 时不要因总超时直接进主界面。
   521	     * 地图事项若被 GNSS/LFS 拖住：12 s 后进主界面，文件留给 LiveMap。 */
   522	    if (elapsed >= STARTUP_MAX_WAIT_MS &&
   523	        ui->chore != STARTUP_CHORE_SALVAGE) {
   524	        if (ui->chore == STARTUP_CHORE_MAP) {
   525	            LV_LOG_WARN("startup: map timeout, enter live map");
   526	            startup_bar_goal(ui, 100);
   527	            startup_row(ui, "已加载", false);
   528	            startup_begin_exit(ui);
   529	            return;
   530	        }
   531	
   532	        LV_LOG_WARN("startup: timeout, skip to map");
   533	#ifndef CONFIG_MYVENDOR_FACTORY_MODE
   534	        (void)myvendor_system_font_lv_bind();
   535	        startup_use_sys_status_font(ui);
   536	#endif
   537	        if (!ui->map_opened) {
   538	            (void)map_page_boot_begin_load();
   539	            ui->map_opened = true;
   540	        }
   541	
   542	        lv_snprintf(ui->chore_key, sizeof(ui->chore_key), "%s", "地图加载");
   543	        ui->chore = STARTUP_CHORE_MAP;
   544	        ui->step = STARTUP_STEP_RUN;
   545	        ui->chore_t0 = lv_tick_get();
   546	        startup_bar_goal(ui, 62);
   547	        startup_row(ui, "加载中", true);
   548	        return;
   549	    }
   550	
   551	    switch (ui->step) {
   552	    case STARTUP_STEP_SLIDE_IN:
   553	        if (lv_tick_elaps(ui->chore_t0) < STARTUP_SLIDE_MS) {
   554	            return;
   555	        }
   556	
   557	        ui->step = STARTUP_STEP_RUN;
   558	        return;
   559	
   560	    case STARTUP_STEP_RUN:
   561	        if (!startup_chore_pump(ui)) {
   562	            return;
   563	        }
   564	
   565	        ui->step = STARTUP_STEP_HOLD;
   566	        ui->chore_t0 = lv_tick_get();
   567	        return;
   568	
   569	    case STARTUP_STEP_HOLD:
   570	        if (lv_tick_elaps(ui->chore_t0) < STARTUP_HOLD_MS) {
   571	            return;
   572	        }
   573	
   574	        ui->step = STARTUP_STEP_SLIDE_OUT;
   575	        ui->chore_t0 = lv_tick_get();
   576	        helm_splash_slide_out(&ui->splash);
   577	        return;
   578	
   579	    case STARTUP_STEP_SLIDE_OUT:
   580	        if (lv_tick_elaps(ui->chore_t0) < STARTUP_SLIDE_MS) {
   581	            return;
   582	        }
   583	
   584	        next = startup_chore_next(ui->chore);
   585	        if (next < STARTUP_CHORE_COUNT) {
   586	            startup_arm_chore(ui, next);
   587	            return;
   588	        }
   589	
   590	        if (ui->ready_tick == 0u) {
   591	            ui->ready_tick = lv_tick_get();
   592	        }
   593	
   594	        if (lv_tick_elaps(ui->ready_tick) < STARTUP_READY_HOLD_MS) {
   595	            return;
   596	        }
   597	
   598	        startup_begin_exit(ui);
   599	        return;
   600	
   601	    default:
   602	        return;
   603	    }
   604	}
