   657	static void startup_will_appear(void * pm_page)
   658	{
   659	    lv_pm_page_t page = lv_pm_get_pm_page(pm_page);
   660	    startup_page_t * ui = page ? (startup_page_t *)page->user_data : NULL;
   661	    if (!ui || !page || !page->page) {
   662	        return;
   663	    }
   664	
   665	    ui->exiting = false;
   666	    ui->chore = STARTUP_CHORE_SALVAGE;
   667	    ui->step = STARTUP_STEP_SLIDE_IN;
   668	    ui->map_opened = false;
   669	    ui->bg_started = false;
   670	    ui->sound_wait = true;
   671	    ui->bg_applied = -1;
   672	    ui->bar_goal = 0xff;
   673	    ui->appear_tick = lv_tick_get();
   674	    ui->ready_tick = 0;
   675	    ui->chore_t0 = 0;
   676	    ui->chore_key[0] = '\0';
   677	    ui->splash.shown[0] = '\0';
   678	    ui->splash.pending[0] = '\0';
   679	    ui->splash.tick_on = false;
   680	    ui->splash.out_busy = false;
   681	
   682	    lv_obj_move_foreground(page->page);
   683	    lv_obj_clear_flag(page->page, LV_OBJ_FLAG_HIDDEN);
   684	    helm_splash_set_chrome_hidden(&ui->splash, true);
   685	    helm_splash_bar_set(&ui->splash, 0);
   686	    startup_lock_black_style(page->page);
   687	    /* 先锁黑防主题米色，再按主题铺回 splash 底色（日=白 / 夜=黑）；
   688	     * 之后 APPEAR_DONE 的 sync_boot 也按同一颜色重铺。 */
   689	    startup_apply_bg(ui, startup_theme_gray());
   690	    startup_play_show_anim(ui);
   691	    myvendor_sound_boot();
   692	    startup_stop_bg_anim(ui);
   693	
   694	    if (ui->poll_timer) {
   695	        lv_timer_del(ui->poll_timer);
   696	        ui->poll_timer = NULL;
   697	    }
   698	
   699	    if (myvendor_sound_idle()) {
   700	        ui->sound_wait = false;
   701	        startup_start_bg_anim(ui);
   702	        return;
   703	    }
   704	
   705	    startup_start_poll(ui);
   706	}
